-- Preset avatars: the owner chose the "Blob buddies" set (blob-01 … blob-24,
-- generated by scripts/generate-avatars.mjs into apps/web/public/avatars/).
-- Only ids that exist as files are accepted. Adding presets means a new
-- migration widening this check.
alter table public.profiles drop constraint profiles_avatar_preset_check;
alter table public.profiles add constraint profiles_avatar_preset_check
  check (avatar_preset ~ '^blob-(0[1-9]|1[0-9]|2[0-4])$');
